use limits::{codegen, interp::Interpreter, lexer, parser, vm::Vm};
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};

struct Count;
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
static REALLOCS: AtomicUsize = AtomicUsize::new(0);
static BYTES: AtomicUsize = AtomicUsize::new(0);
static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);
fn record(n: usize) {
    BYTES.fetch_add(n, Relaxed);
    let live = LIVE.fetch_add(n, Relaxed) + n;
    PEAK.fetch_max(live, Relaxed);
}
unsafe impl GlobalAlloc for Count {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        let p = System.alloc(l);
        if !p.is_null() { ALLOCS.fetch_add(1, Relaxed); record(l.size()); }
        p
    }
    unsafe fn alloc_zeroed(&self, l: Layout) -> *mut u8 {
        let p = System.alloc_zeroed(l);
        if !p.is_null() { ALLOCS.fetch_add(1, Relaxed); record(l.size()); }
        p
    }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        LIVE.fetch_sub(l.size(), Relaxed);
        System.dealloc(p, l);
    }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 {
        let p = System.realloc(p, l, n);
        if !p.is_null() {
            REALLOCS.fetch_add(1, Relaxed);
            BYTES.fetch_add(n, Relaxed);
            if n >= l.size() {
                let live = LIVE.fetch_add(n-l.size(), Relaxed) + n-l.size();
                PEAK.fetch_max(live, Relaxed);
            } else { LIVE.fetch_sub(l.size()-n, Relaxed); }
        }
        p
    }
}
#[global_allocator]
static GLOBAL: Count = Count;

fn main() {
    for n in [18, 25] {
        for (label, extra) in [("frame_only", ""), ("local_scope", "let copy=n;"), ("captured_scope", "fn captured(){return n;}")] {
            let source = format!("fn fib(n){{{extra}if n<2{{return n;}}return fib(n-1)+fib(n-2);}}print(fib({n}));");
            let ast = parser::parse(lexer::lex(&source).unwrap()).unwrap();
            let compiled = codegen::compile(&ast).unwrap();
            for engine in ["tree", "vm"] {
                // Warmup and measurement use fresh runtimes/output. AST/bytecode
                // construction is outside the allocation measurement.
                for measured in [false, true] {
                    let mut output = Vec::new();
                    let base_live = LIVE.load(Relaxed);
                    let base_alloc = ALLOCS.load(Relaxed);
                    let base_realloc = REALLOCS.load(Relaxed);
                    let base_bytes = BYTES.load(Relaxed);
                    PEAK.store(base_live, Relaxed);
                    if engine == "vm" { Vm::new(&mut output).run(compiled.clone()).unwrap(); }
                    else { Interpreter::new(&mut output).run(&ast).unwrap(); }
                    let allocs = ALLOCS.load(Relaxed) - base_alloc;
                    let reallocs = REALLOCS.load(Relaxed) - base_realloc;
                    let bytes = BYTES.load(Relaxed) - base_bytes;
                    let peak = PEAK.load(Relaxed) - base_live;
                    let net = LIVE.load(Relaxed) as i128 - base_live as i128;
                    assert_eq!(output, if n==18 { b"2584\n".as_slice() } else { b"75025\n".as_slice() });
                    if measured {
                        println!("{{\"record\":\"allocation_probe\",\"workload\":\"fib{n}_{label}\",\"engine\":\"{engine}\",\"calls\":{},\"alloc_calls\":{allocs},\"realloc_calls\":{reallocs},\"requested_bytes_including_realloc\":{bytes},\"peak_live_requested_bytes_delta\":{peak},\"retained_requested_bytes_after_runtime_drop\":{net}}}", if n==18 {8361} else {242785});
                    }
                }
            }
        }
    }
}
